window.SBL_IGCSE_PPQ = {"topic": "Development and Human Welfare", "img": "/igcse/geography/learn/past-papers-img/", "lessons": {"IGDV01": {"n": 1, "title": "What is development and what factors contribute to a country's development?", "href": "/igcse/geography/learn/development-and-human-welfare/l01-what-is-development"}, "IGDV02": {"n": 2, "title": "Measuring development: GDP per capita", "href": "/igcse/geography/learn/development-and-human-welfare/l02-measuring-development-gdp"}, "IGDV03": {"n": 3, "title": "Measuring development: HDI, Gini coefficient and corruption", "href": "/igcse/geography/learn/development-and-human-welfare/l03-hdi-gini-and-corruption"}, "IGDV04": {"n": 4, "title": "Demographic data and the demographic transition model", "href": "/igcse/geography/learn/development-and-human-welfare/l04-demographic-transition-model"}, "IGDV05": {"n": 5, "title": "Demographic transition model and population pyramids", "href": "/igcse/geography/learn/development-and-human-welfare/l05-population-pyramids"}, "IGDV06": {"n": 6, "title": "Causes of uneven development", "href": "/igcse/geography/learn/development-and-human-welfare/l06-causes-of-uneven-development"}, "IGDV07": {"n": 7, "title": "Causes of uneven development within countries: Italy case study", "href": "/igcse/geography/learn/development-and-human-welfare/l07-italy-uneven-development"}, "IGDV08": {"n": 8, "title": "International strategies to reduce the development gap", "href": "/igcse/geography/learn/development-and-human-welfare/l08-reducing-the-development-gap"}, "IGDV09": {"n": 9, "title": "Case studies: Development projects in Nigeria and Kenya", "href": "/igcse/geography/learn/development-and-human-welfare/l09-nigeria-and-kenya-projects"}}, "parts": [{"key": "P2-2024-9ai", "paper": "2024", "paperLabel": "June 2024 · Paper 2", "q": 9, "id": "9(a)(i)", "marks": 1, "text": "Identify the definition of gross domestic product (GDP).", "intro": "", "options": [["A", "a measure of development including health and income"], ["B", "a measure of improvement in inequality"], ["C", "the total value of all imports within a country in a year"], ["D", "the total value of goods and services produced by a country in a year"]], "answer": "D", "type": "mcq", "lesson": "IGDV02", "ms": "AO1 (1 mark) (1)\n\nD the total value of all goods and services produced by a country in a year (1)\n\nThe answer cannot be A, B, or C as these are not definitions of gross domestic product (GDP).", "sources": []}, {"key": "P2-2024-9aii", "paper": "2024", "paperLabel": "June 2024 · Paper 2", "q": 9, "id": "9(a)(ii)", "marks": 1, "text": "Identify an organisation that attempts to address the global development gap.", "intro": "", "options": [["A", "United States Geological Survey"], ["B", "North American Free Trade Association (NAFTA)"], ["C", "North Atlantic Treaty Organisation (NATO)"], ["D", "World Bank"]], "answer": "D", "type": "mcq", "lesson": "IGDV08", "ms": "AO1 (1 mark) (1)\n\nD World Bank (1).\n\nThe answer cannot be A as this is an organisation that focuses on science and hazards, B is a trade bloc and C is a security system.", "sources": []}, {"key": "P2-2024-9aiii", "paper": "2024", "paperLabel": "June 2024 · Paper 2", "q": 9, "id": "9(a)(iii)", "marks": 1, "text": "State one way countries may use international aid to support development.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV08", "ms": "AO1 (1 mark) (1)\n\nAward 1 mark for a suitable way identified.\n\n• Invest in education (1).\n• Build infrastructure (1)\n• To relieve poverty (1).\n• To provide suitable equipment/technology (1)\n• Training (1)\n• Micro-loans / financial support / loans (1)\n\nAccept any other appropriate response.", "sources": []}, {"key": "P2-2024-9bi", "paper": "2024", "paperLabel": "June 2024 · Paper 2", "q": 9, "id": "9(b)(i)", "marks": 2, "text": "Study Figure 9a in the Resource Booklet. Identify two labelled countries with the highest life expectancy.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV01", "ms": "AO3 (2 marks) (2)\n\nAward 1 mark for each of the following.\n\n• Spain (1)\n• Australia (1)", "sources": [{"src": "p2-2024-q9-p68.jpg", "figs": ["9a"]}]}, {"key": "P2-2024-9bii", "paper": "2024", "paperLabel": "June 2024 · Paper 2", "q": 9, "id": "9(b)(ii)", "marks": 4, "text": "Suggest two reasons for the pattern shown in Figure 9a.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV01", "ms": "AO2/AO3 (4 marks) (4)\n\nAward 1 mark for identification of a pattern, with a further mark for development with reference to the resource, up to a maximum of 2 marks. Do not double credit mirrored reasons.\n\n• There is significant variation in life expectancy in South America (1), which could be due to variable access to healthcare which could lead to reduced life expectancy (1).\n\n• There are generally high life expectancies experienced across Europe (1) as these are considered developed countries with good healthcare systems (1).\n\n• Generally longer life expectancy in North America (1) due to higher incomes which can be used for better diet (1).\n\nAccept any other appropriate response.\n\nAccept a pattern to be a reference to more than one country.", "sources": [{"src": "p2-2024-q9-p68.jpg", "figs": ["9a"]}]}, {"key": "P2-2024-9c", "paper": "2024", "paperLabel": "June 2024 · Paper 2", "q": 9, "id": "9(c)", "marks": 4, "text": "Explain one advantage and one disadvantage of top-down development projects.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV09", "ms": "AO1/AO2 (4 marks) (4)\n\nAward 1 mark for identification of suitable advantage and a disadvantage, with a further mark for development or explanation, up to a maximum of 2 marks.\n\nAdvantages\n• Often involve large sums of investment (1) which can involve large international or national organisations (1).\n• Can provide opportunities to improve infrastructure (1) which can have a positive effect on a wide range of people/sectors (1).\n• Potential for larger economic impact (1) due to the large scale of the project (1).\n\nDisadvantages\n• Often requires large amounts of money (1) which may lead or tied loans/create debt for the country (1).\n• Tend not to have involvement from local people (1) so may not have desired impact for development (1).\n• Does not always use appropriate technology (1) which means local people don’t always benefit (1).\n\nAccept any other appropriate response.", "sources": []}, {"key": "P2-2024-9di", "paper": "2024", "paperLabel": "June 2024 · Paper 2", "q": 9, "id": "9(d)(i)", "marks": 2, "text": "Study Figure 9b in the Resource Booklet. Calculate the range in the number of people affected by food insecurity in Nigeria, 2015–2019. You must show all your workings in the space below.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV06", "ms": "AO4 (2 marks) (2)\n\nAward 1 mark for correct method and a further mark for correct answer.\n\n• 120-68 (1) Allow 119-20 and allow 68-69\n• 52 (1) Accept answers in the range 50-52", "sources": [{"src": "p2-2024-q9-p69.jpg", "figs": ["9b"]}]}, {"key": "P2-2024-9dii", "paper": "2024", "paperLabel": "June 2024 · Paper 2", "q": 9, "id": "9(d)(ii)", "marks": 2, "text": "Describe a trend shown.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV06", "ms": "AO4 (2 marks) (2)\n\nAward 1 mark for the identification of suitable trends and a further mark for description, which could include the use of data, up to a maximum or 2 marks.\n\n• Many countries have consistently had consistent numbers of people experiencing food insecurity (1) for example Bangladesh has been around 50 million from 3015-2019 (1).\n• Nigeria has experienced a significant increase in people experiencing food security (1) from 6 million to around\n(1)\n• Brazil has experienced some fluctuation in the number of people experiencing food insecurity (1) fluctuating 38 and 48 million (1).\n• Most countries have an increase in food insecurity (1) with the exception of Estonia which stays around the same level (1).\n\nAccept any other appropriate response.", "sources": [{"src": "p2-2024-q9-p69.jpg", "figs": ["9b"]}]}, {"key": "P2-2024-9e", "paper": "2024", "paperLabel": "June 2024 · Paper 2", "q": 9, "id": "9(e)", "marks": 6, "text": "Study Figure 9c in the Resource Booklet. Assess how useful the Human Development Index (HDI) is for understanding patterns of development. You must refer to the resource in your answer.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV03", "ms": "AO3 (3 marks)/AO4 (3 marks)\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the levels-based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. Relevant points may include:\n\nAO3\n• The Human Development Index is a composite index which is used to measure a country’s development, using a combination of life expectancy, years of schooling and GNI per capita.\n• HDI is a widely used measures of quality of life. The scores range from 0 to 1. The higher the HDI, this indicates a higher level of development and a higher quality of life.\n• HDI uses a mixture of three indicators which means it takes into account more measures than just using single indicators such as GNP/GNI/per capita income, or life expectancy.\n• The scores are still made at a national level and therefore they mask levels of inequality and differences in development within countries.\n• There are a range of economic, social, and political indicators that can be used to measure development that are not included in the HDI (e.g. birth rate, people per doctor, Gini equality index).\n\nAO4\n• Figure 9c shows how the human development index has three key dimensions.\n• Figure 9c shows how the dimension of living a long and healthy life is measured through life expectancy.\n• Figure 9c shows how the knowledge dimension is measured through expected years of schooling.\n• Figure 9c shows how the decent standard of living is measures through GNI per capita.\n\nLevel Mark Descriptor 0 No rewardable material.\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\n\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)", "sources": [{"src": "p2-2024-q9-p70.jpg", "figs": ["9c"]}]}, {"key": "P2-2024-9f", "paper": "2024", "paperLabel": "June 2024 · Paper 2", "q": 9, "id": "9(f)", "marks": 12, "text": "Discuss the view: “Improvements in human welfare are mainly driven by economic development.” Use Figures 9b and 9c from the Resource Booklet, and your own knowledge and understanding to support your answer. You must refer to the resources in your answer.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV01", "ms": "AO2 (4 marks), AO3 (4 marks), AO4 (4 marks)\n\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the levels-based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. Relevant points may include:\n\nAO2\n• Human welfare of a country can be affected by a range of factors economic, social, technological, and cultural.\n• Growth in GDP and other economic indicators are often associated with improved human welfare.\n• Improvements in human welfare are often associated with improvements in life expectancy, mortality rates.\n\nAO3\n• Development is often understood through economic terms through GDP etc. which does not necessarily reflect overall development of a country in terms of quality of life.\n• Social measures of development could include inequality which may more accurately portray the overall development of a country rather than an increase in wealth, which could have been fuelled by discovery of natural resources, or growth in a particular industry.\n• Patterns of development are often discussed at the national level, whereas there are significant variations within social and economic experiences within countries.\n• Human welfare issues are complex and while improvements in economic terms at the national scale may suggest development, the pattern may be uneven. Improvements to housing, education and healthcare are key social issues that lead to increased human welfare, but they all have an economic cost.\nAO4\n\n• Figure 9b shows variations in the number of people who experience food insecurity in 2015-2019.\n• Figure 9b shows how many of the selected countries in Africa have a consistent level of people who experienced food insecurity during 2015-2019.\n• Figure 9b shows how Nigeria has had a rising number of people who experience food insecurity in 2015-2019.\n• Figure 9c shows how the human development index has three key dimensions.\n• Figure 9c shows how the dimension of living a long and healthy life is measured through life expectancy.\n• Figure 9c shows how the knowledge dimension is measured through expected years of schooling.\n• Figure 9c shows how the decent standard of living is measures through GNI per capita.\nLevel Mark Descriptor 0 No acceptable response.\nLevel 1 1–4 • Demonstrates isolated elements of understanding of concepts and the interrelationship between places, environments and processes. (AO2)\n• Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements are supported by limited evidence. (AO3)\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (A04)\nLevel 2 5–8 • Demonstrates elements of understanding of concepts and the interrelationship between places, environments and processes. (AO2)\n• Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\nLevel 3 9–12 • Demonstrates accurate understanding of concepts and the interrelationship of places, environments and processes. (AO2)\n• Applies understanding to deconstruct information and provides logical connections between concepts throughout. A balanced, well-developed argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4) with its registered office at 80 Strand, London, WC2R 0RL, United Kingdom", "sources": [{"src": "p2-2024-q9-p69.jpg", "figs": ["9b"]}, {"src": "p2-2024-q9-p70.jpg", "figs": ["9c"]}]}, {"key": "P2-2023R-9ai", "paper": "2023R", "paperLabel": "June 2023 · Paper 2R", "q": 9, "id": "9(a)(i)", "marks": 1, "text": "Identify which of the following would be best to measure a country’s development.", "intro": "", "options": [["A", "Climate Change Performance Index"], ["B", "Environmental Quality Index"], ["C", "Flood Risk Index"], ["D", "Human Development Index"]], "answer": "D", "type": "mcq", "lesson": "IGDV02", "ms": "AO1 (1 mark)\n\nD Human Development Index (1) (1)\n\nThe answer cannot be A, B or C as they cannot be used to measure development.", "sources": []}, {"key": "P2-2023R-9aii", "paper": "2023R", "paperLabel": "June 2023 · Paper 2R", "q": 9, "id": "9(a)(ii)", "marks": 1, "text": "Identify a reason for lower mortality rates in developed countries.", "intro": "", "options": [["A", "improved access to retail services"], ["B", "improved access to healthcare services"], ["C", "improved access to airports"], ["D", "improved access to legal services"]], "answer": "B", "type": "mcq", "lesson": "IGDV04", "ms": "AO1 (1 mark)\n\nB improved access to healthcare services (1). (1)\n\nThe answer cannot be A, C or D as these are not suitable reasons for a falling mortality rate in a developing country.", "sources": []}, {"key": "P2-2023R-9b", "paper": "2023R", "paperLabel": "June 2023 · Paper 2R", "q": 9, "id": "9(b)", "marks": 2, "text": "State one reason why there are different measures of development.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV02", "ms": "AO1 (2 marks)\n\nAward 1 mark for a suitable reason, and a further mark for development or explanation, up to a maximum of 2 marks.\n\n• Some measures of development only focus on one element of development (1) e.g. GDP provides an economic measure.(1)\n\n• Some composite indices such as HDI are made up of (2) different measurements (1) such as years of schooling and GNP per capita (1).\n\n• Development is complex (1) and can be measured using different ways such as GDP or literacy rate (1).\n\nAccept any other appropriate response.", "sources": []}, {"key": "P2-2023R-9ci", "paper": "2023R", "paperLabel": "June 2023 · Paper 2R", "q": 9, "id": "9(c)(i)", "marks": 1, "text": "Study Figure 9a in the Resource Booklet Identify the country labelled in Figure 9a with the lowest level of GDP per capita.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV02", "ms": "AO3 (1 mark)\n\nAward 1 mark for:\n\n• Chad (1)\n\n(1)", "sources": [{"src": "p2-2023R-q9-p73.jpg", "figs": ["9a"]}]}, {"key": "P2-2023R-9cii", "paper": "2023R", "paperLabel": "June 2023 · Paper 2R", "q": 9, "id": "9(c)(ii)", "marks": 2, "text": "Compare the pattern for Europe and South America shown in Figure 9a.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV02", "ms": "AO4 (2 marks)\n\nAward 1 mark for initial comparative statement, and a further mark for development or use of suitable data, up to a maximum of 2 marks per idea.\n\n• Europe has more countries with a higher GDP per capita than South America (1). Most countries in Europe are US$25,000 or more (1).\n\n• There is a greater range in GDP in South America than in Europe (1), ranging from under US$500 up to 10- 25,000 (1).\n\nAccept any other appropriate response. (2)", "sources": [{"src": "p2-2023R-q9-p73.jpg", "figs": ["9a"]}]}, {"key": "P2-2023R-9ciii", "paper": "2023R", "paperLabel": "June 2023 · Paper 2R", "q": 9, "id": "9(c)(iii)", "marks": 2, "text": "Suggest one possible reason for the pattern shown in Figure 9a.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV02", "ms": "AO2 (2 marks)\n\nAward 1 mark (AO1) for identification of suitable reason, with a further mark for development or explanation, up to a maximum of 2 marks.\n\n• Developing or emerging economies are more likely to have lower GDP per capita (1) as they tend to have had historically lower growth. (1).\n\n• The pattern displays global patterns of economic development (1) where many developing and emerging countries have lower economic development indicators (1).\n\nAccept any other appropriate response.\n\n(2)", "sources": [{"src": "p2-2023R-q9-p73.jpg", "figs": ["9a"]}]}, {"key": "P2-2023R-9civ", "paper": "2023R", "paperLabel": "June 2023 · Paper 2R", "q": 9, "id": "9(c)(iv)", "marks": 2, "text": "Explain why the data shown in Figure 9a may not show an accurate picture of global development.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV02", "ms": "AO2 (1 mark) / AO3 (1 mark)\n\nAward 1 mark for a suitable reason, and a further mark for development or explanation, up to a maximum of 2 marks.\n\n• Development can be measured by more than just economic indicators (1) for example literacy rate, or composite indices such as the HDI (1).\n• GNP per capita does not provide information about spread of income across society (1) so some countries may be more developed in terms of inequality than others but it would not be shown with this indicator (1).\n(2)\n• Data does include all countries (1) which may hide different patterns of development (1).", "sources": [{"src": "p2-2023R-q9-p73.jpg", "figs": ["9a"]}]}, {"key": "P2-2023R-9d", "paper": "2023R", "paperLabel": "June 2023 · Paper 2R", "q": 9, "id": "9(d)", "marks": 2, "text": "State two quality of life indicators other than GDP per capita.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV02", "ms": "AO1 (2 marks)\n\nAward 1 mark for the identification of each suitable quality of life indicator, up to a maximum of two marks.\n\n• Literacy rate (1)\n• Employment rate (1)\n• Infant mortality rate (1)\n• Life expectancy (1)\n• Physical quality of life index (1)\n• Corruption index (1).\n• Human Development Index (HDI) (1) (2)\n\nAllow GNI or GNI per capita, but do not credit GDP or GDP per capita\n\nAccept any other appropriate response.", "sources": []}, {"key": "P2-2023R-9e", "paper": "2023R", "paperLabel": "June 2023 · Paper 2R", "q": 9, "id": "9(e)", "marks": 4, "text": "Explain two impacts of uneven development within a country.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV07", "ms": "AO1 (2 marks) / AO2 (2 marks)\n\nAward 1 mark for the identification of a suitable impact of uneven development within a country, up to a maximum of 2 marks for each point. Award marks for up to two different ways.\n\n• Uneven development of a country’s infrastructure means that some areas remain undeveloped (1) and people may not have access to basic services such as healthcare (1).\n\n• Development focused in cities can lead to more rural to urban migration (1) leading to rural isolation and poverty (1).\n\n• Core-periphery theory suggests economic development (4) and wealth generation are focused in a particular region (1) which leads other regions poor by comparison because there is less investment and they have to wait for wealth to trickle down from the core (1).\nAccept any other appropriate response.", "sources": []}, {"key": "P2-2023R-9f", "paper": "2023R", "paperLabel": "June 2023 · Paper 2R", "q": 9, "id": "9(f)", "marks": 6, "text": "Study Figure 9b in the Resource Booklet. Assess the different views on how to tackle the development gap. Refer to the resource in your answer.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV08", "ms": "AO3 (3 marks)/AO4 (3 marks)\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the levels-based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. Relevant points may include:\n\nAO3\n• There are different approaches to tackling the development gap:\no Top-down approaches are usually government (or international organisation) led and usually have little involvement of local people with the focus on major financial investment often in infrastructure or services. They can be prone to over-run in time and costs, and sometimes susceptible to corruption so the benefits don’t reach those intended.\no Bottom-up approaches are usually much more locally focused and often ran by NGOs in collaboration with local people to support their needs at a smaller scale.\n• Bottom-up projects tend not to be as expensive as they operate on a smaller scale and tend to use more locally appropriate technologies.\n• Bottom-up development projects often focus on develop skills and capabilities within local communities so they can continue the development process once the initial project has finished for example training in sustainable agriculture techniques, or methods for developing micro-hydro schemes.\n• While bottom-up schemes may support local communities effectively than top-down approaches they are unlikely to change wider systemic issues that are affecting the development of the country such as inequality or lack of infrastructure to support economic development.\n• Top-down approaches typically involve large investments from government or international institutions designed to support infrastructure or institutions which can in turn foster development.\n\nAO4\n• Figure 9b show three views about strategies for tackling the development gap (from government, intergovernmental agencies and an NGO).\n• Figure 9b indicates how strategies to tackle the development gap can take place at different scales.\n• Figure 9b provides examples of the types of activities bottom-up approaches (to provide access to lighting) as well as top down (investment and financial support).\n\nLevel Mark Descriptor 0 No rewardable material.\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\n\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\n•\nIndicative content\nQuestion", "sources": [{"src": "p2-2023R-q9-p74.jpg", "figs": ["9b"]}]}, {"key": "P2-2023R-9g", "paper": "2023R", "paperLabel": "June 2023 · Paper 2R", "q": 9, "id": "9(g)", "marks": 12, "text": "Discuss the view: “Uneven global development can be reduced most effectively through international aid.” Use Figures 9a and 9b from the Resource Booklet, and your own knowledge and understanding to support your answer. Refer to the resources in your answer.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV08", "ms": "AO2 (4 marks), AO3 (4 marks), AO4 (4 marks)\n\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the levels-based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. Relevant points may include:\nInternational strategies to address uneven development are the most effective\nAO2\n• International strategies to address uneven global development can include bilateral aid, multilateral aid, or aid co-ordinated through organisations such as the World Bank or IMF (most commonly loans).\n• Often governments have their own economic development strategies, e.g. Bangladesh has made a series of 5-year plans on its own economic development support by plans for different issues within its country.\n• NGO usually take a bottom-up approach to reducing uneven development focusing on small communities and a particular element of quality of life such as water, food, housing or education.\n\nAO3\n• Many would argue that patterns of, and factors affecting global uneven development are too complex to be addressed by one type of strategy and that collaboration between international, national and local stakeholders is necessary to support development.\n• International strategies such as financing large scale infrastructure projects such as cross-national highways or international airports or ports can act as a catalyst for economic development through the creation of jobs and the attraction of inward investment which can lead to economic growth.\n• International strategies such as financial aid in the form of loans from the IMF have exacerbated issues of uneven development as it can lead to dependency on financial support, can lead to exploitation of natural resources, or lead to some development projects costing more than necessary. Infrastructure projects don’t necessarily lead to benefits for all people.\n• International strategies in the form of aid (and investment) can also be susceptible to corruption so the money does not necessarily benefit those it was intended to and therefore does not improve uneven development.\nIndicative content\nQuestion\n\nAO4\n\n• Figure 9a shows how the global distribution of GDP per capita is uneven.\n• Figure 9a shows how countries considered developed tend to have higher GDP per capita with much of Europe, North America and Oceania with US$25,000 or more.\n• Figure 9a shows how some regions have much larger range in GDP too, with Asia including high GDP for countries like Japan but much lower in South East Asia.\n• Figure 9b show three views about strategies for tackling the development gap (from government, intergovernmental agencies and an NGO).\n• Figure 9b indicates how strategies to tackle the development gap can take place at different scales.\n• Figure 9b provides examples of the types of activities bottom-up approaches (to provide access to lighting) as well as top down (investment and financial support).\n\nLevel Mark Descriptor 0 No acceptable response.\nLevel 1 1–4 • Demonstrates isolated elements of understanding of concepts and the interrelationship between places, environments and processes. (AO2)\n• Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements are supported by limited evidence. (AO3)\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (A04)\nLevel 2 5–8 • Demonstrates elements of understanding of concepts and the interrelationship between places, environments and processes. (AO2)\n• Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\nLevel 3 9–12 • Demonstrates accurate understanding of concepts and the interrelationship of places, environments and processes. (AO2)\nIndicative content\nQuestion\n• Applies understanding to deconstruct information and provides logical connections between concepts throughout. A balanced, well-developed argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4) with its registered office at 80 Strand, London, WC2R 0RL, United Kingdom", "sources": [{"src": "p2-2023R-q9-p73.jpg", "figs": ["9a"]}, {"src": "p2-2023R-q9-p74.jpg", "figs": ["9b"]}]}, {"key": "P2-2022-9ai", "paper": "2022", "paperLabel": "June 2022 · Paper 2", "q": 9, "id": "9(a)(i)", "marks": 1, "text": "Identify the indicator used to calculate the Human Development Index (HDI).", "intro": "", "options": [["A", "infant mortality rate"], ["B", "access to water"], ["C", "life expectancy"], ["D", "houses with electricity"]], "answer": "C", "type": "mcq", "lesson": "IGDV03", "ms": "AO1 (1 mark)\n\nC Life expectancy (1).\n\nThe answer cannot be A, B, or D as these are not used to calculate the Human Development Index.\n(1)", "sources": []}, {"key": "P2-2022-9aii", "paper": "2022", "paperLabel": "June 2022 · Paper 2", "q": 9, "id": "9(a)(ii)", "marks": 1, "text": "Identify the correct word to complete the sentence below: The … can be used to measure inequality.", "intro": "", "options": [["A", "adult literacy rate"], ["B", "Gini-coefficient"], ["C", "rate of natural increase"], ["D", "dependency ratio"]], "answer": "B", "type": "mcq", "lesson": "IGDV03", "ms": "AO1 (1 mark)\n\nB Gini-coefficient (1).\n\nThe answer cannot be A (this measures literacy), C (measures population increase), or D (focuses on relationship between older and younger populations).\n(1)", "sources": []}, {"key": "P2-2022-9bi", "paper": "2022", "paperLabel": "June 2022 · Paper 2", "q": 9, "id": "9(b)(i)", "marks": 1, "text": "Define the term development gap.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV06", "ms": "AO1 (1 mark)\n• The difference in levels of development and standards of living between countries/regions (1).\n\nAccept any other appropriate response. (1)", "sources": []}, {"key": "P2-2022-9bii", "paper": "2022", "paperLabel": "June 2022 · Paper 2", "q": 9, "id": "9(b)(ii)", "marks": 2, "text": "Study Figure 9a in the Resource Booklet Identify two countries labelled in Figure 9a with a Corruption Perception Index score between 80–100.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV03", "ms": "AO3 (2 marks)\n\nAward 1 mark for any of the following, up to a maximum of 2 marks.\n\n• USA (1).\n• UK (1). (2)", "sources": [{"src": "p2-2022-q9-p67.jpg", "figs": ["9a"]}]}, {"key": "P2-2022-9biii", "paper": "2022", "paperLabel": "June 2022 · Paper 2", "q": 9, "id": "9(b)(iii)", "marks": 4, "text": "Suggest two possible reasons for the pattern shown in Figure 9a.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV03", "ms": "AO2 (2 marks) / AO3 (2 marks)\n\nAward 1 mark for the identification of a possible reason for the pattern shown on Figure 9a (AO3) and a further mark for an explanation of the reason (AO2), up to a maximum of 2 marks per idea.\n\n• High levels of political corruption may hinder the development process of a country (1) as money needed for development project might not reach the right places (1).\n\n• High levels of corruption in developing countries may mean that money donated to governments as aid may not reach the right people (1) which means they cannot improve their quality of life (1).\n\n• Countries with lower levels of corruption such as the US and UK can operate more efficiently (1) allowing economic development to impact more of their population (1).\n(4)\nAccept any other appropriate response.", "sources": [{"src": "p2-2022-q9-p67.jpg", "figs": ["9a"]}]}, {"key": "P2-2022-9c", "paper": "2022", "paperLabel": "June 2022 · Paper 2", "q": 9, "id": "9(c)", "marks": 4, "text": "Explain how fertility rates and population structures change as a country becomes more developed.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV04", "ms": "AO1 (2 marks) / AO2 (2 marks)\nAward 1 mark (AO1) for identification of the change and a further mark (AO2) for an explanation, up to a maximum of 2 marks per idea:\n\n• Fertility rates\no Fertility rates decrease (1) because people gain better access to healthcare services (1).\no Fertility rates decrease (1) because people have access to more information about contraception (1).\n\n• Population Structure\no More older people in developed countries (1) because of increased life expectancy (1)\no Fewer young age groups in developed countries (1) because of reduced fertility rates (1).\n\nAccept any other appropriate response. (4)", "sources": []}, {"key": "P2-2022-9di", "paper": "2022", "paperLabel": "June 2022 · Paper 2", "q": 9, "id": "9(d)(i)", "marks": 2, "text": "Study Figure 9b in the Resource Booklet. Calculate the range in the mortality rates for India between 1990–2018. You must show all your workings in the space below. Give your answer to one decimal place.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV04", "ms": "AO4 (2 marks)\n\nAward 1 mark for a correct answer and one mark for working:\n\nHighest = 10.9 Lowest = 7.2 (1).\n\nRange = 3.7 (1). Accept answers from 3.5-3.9\n(2)", "sources": [{"src": "p2-2022-q9-p68.jpg", "figs": ["9b"]}]}, {"key": "P2-2022-9dii", "paper": "2022", "paperLabel": "June 2022 · Paper 2", "q": 9, "id": "9(d)(ii)", "marks": 2, "text": "Suggest how this trend might compare to a developed country such as Canada.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV04", "ms": "AO3 (2 marks)\nAward 1 mark for the identification of a pattern and 1 mark for further detail linked to development, up to a maximum of 2 marks.\n\n• India’s mortality rate declined by nearly 4 per 1,000 (1) whereas a developed country is likely to have had a lower mortality rate during this time period (1).\n\n• India’s mortality rate reduced (1) whereas a developed country will not have experienced such a steep decline (1).\n\nAccept any other appropriate response.\n(2)", "sources": [{"src": "p2-2022-q9-p68.jpg", "figs": ["9b"]}]}, {"key": "P2-2022-9e", "paper": "2022", "paperLabel": "June 2022 · Paper 2", "q": 9, "id": "9(e)", "marks": 6, "text": "Study Figure 9c in the Resource Booklet. Assess the different views on the use of bottom-up projects to improve quality of life.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV09", "ms": "AO3 (3 marks)/AO4 (3 marks)\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the levels-based mark scheme below.\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. Relevant points may include:\n\nAO3\n• Bottom-up projects are development project that tend to be focused on local communities, and will often include involvement of local people.\n• Some views suggest a top-down approach could be preferable in terms of needing large scale investments, or having an impact at a national scale, while others suggest focusing on the household level most likely through bottom-up projects.\n• Each of the suggestions has the potential to make improvements, but potentially over different timescales.\n\nAO4\n• Figure 9c shows views on a bottom-up development projects, with each taking a different focus.\n• Figure 9c shows there are a range of views from different groups of people including governments, organisations and individuals.\n• Figure 9c shows how the different views suggest actions at a range of different scales, with different priorities.\n\nLevel Mark Descriptor 0 No rewardable material.\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)", "sources": [{"src": "p2-2022-q9-p69.jpg", "figs": ["9c"]}]}, {"key": "P2-2022-9f", "paper": "2022", "paperLabel": "June 2022 · Paper 2", "q": 9, "id": "9(f)", "marks": 12, "text": "Discuss the view ‘Top-down projects are the most effective for tackling the development gap between countries.’ Use Figures 9a and 9c from the Resource Booklet, and your own knowledge and understanding to support your answer.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV09", "ms": "AO2 (4 marks), AO3 (4 marks), AO4 (4 marks)\n\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the levels-based mark scheme below.\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. Relevant points may include:\n\nAO2\n• There are a range of ways to tackle the development gap including top down and bottom up projects.\n• Different factors contribute to the development of a country / region: cultural, technological, social, economic as well as wider measures such as stability and water availability.\nAO3\n• Top down projects often led by international agencies or government organisations often focus on economic investment/debt, large scale infrastructure or systems that can help foster economic development with the benefits trickling down through regions to local people. These are not always the most appropriate methods for tackling the development gap.\n• E.g. The Nigeria Coastal railway designed to link up major cities and settlements near the coast, and encourage development in the delta.\n• Bottom-up development projects usually involve more grass- roots based approaches, focusing on helping people improve their lives. This often involves NGOS and individuals and can include providing financial support (but on a small scale), technical expertise or equipment needed.\n• E.g. Water aid in Kenya providing appropriate technology to improve access to safe drinking water in local communities.\n\nAO4\n\n• Figure 9a shows how political corruption varies globally with few countries having a very low corruption perception, those that do tend to be developed countries.\n• Figure 9a shows how there appears to be some links between political corruption and the level of development.\n• Figure 9c shows how there are range of actors that can be involved in projects to tackle the development gap.\n• Figure 9c shows how tackling the development gap is not just about increasing economic development but improving quality of life too.\n\nLevel Mark Descriptor 0 No acceptable response.\nLevel 1 1–4 • Demonstrates isolated elements of understanding of concepts and the interrelationship between places, environments and processes. (AO2)\n• Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements are supported by limited evidence. (AO3)\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (A04)\nLevel 2 5–8 • Demonstrates elements of understanding of concepts and the interrelationship between places, environments and processes. (AO2)\n• Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\nLevel 3 9–12 • Demonstrates accurate understanding of concepts and the interrelationship of places, environments and processes. (AO2)\n• Applies understanding to deconstruct information and provides logical connections between concepts throughout. A balanced, well-developed argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4) with its registered office at 80 Strand, London, WC2R 0RL, United Kingdom", "sources": [{"src": "p2-2022-q9-p67.jpg", "figs": ["9a"]}, {"src": "p2-2022-q9-p69.jpg", "figs": ["9c"]}]}, {"key": "P2-2022R-9ai", "paper": "2022R", "paperLabel": "June 2022 · Paper 2R", "q": 9, "id": "9(a)(i)", "marks": 1, "text": "Identify the correct word to complete the sentence below. The Human Development Index is created using GNP per capita, years of education and …… .", "intro": "", "options": [["A", "life expectancy"], ["B", "mortality rate"], ["C", "fertility rate"], ["D", "number of doctors per 1,000 people"]], "answer": "A", "type": "mcq", "lesson": "IGDV03", "ms": "AO1 (1 mark)\n\nA life expectancy (1)\n\nThe answer cannot be B, C or D as these are not used to calculate the Human Development Index (HDI). (1)", "sources": []}, {"key": "P2-2022R-9aii", "paper": "2022R", "paperLabel": "June 2022 · Paper 2R", "q": 9, "id": "9(a)(ii)", "marks": 1, "text": "Identify one type of demographic data.", "intro": "", "options": [["A", "Gross National Product (GNP)"], ["B", "Ecological footprint"], ["C", "Corruption Index"], ["D", "Infant mortality rate"]], "answer": "D", "type": "mcq", "lesson": "IGDV04", "ms": "AO1 (1 mark)\n\nD infant mortality rate (1)\nThe answer cannot be A, B or C as these are not forms of demographic data. (1)", "sources": []}, {"key": "P2-2022R-9b", "paper": "2022R", "paperLabel": "June 2022 · Paper 2R", "q": 9, "id": "9(b)", "marks": 1, "text": "Identify one international organisation that tries to reduce the development gap.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV08", "ms": "AO1 (1 mark)\n\nAward 1 mark for a suitable organisation.\n\n• World Bank (1)\n• Oxfam or other international NGO (1)\n• World Health Organisation (1)\n• International Monetary Fund (1)\n• United Nations / UNESCO (1)\n(1)\nAccept any other appropriate response.", "sources": []}, {"key": "P2-2022R-9ci", "paper": "2022R", "paperLabel": "June 2022 · Paper 2R", "q": 9, "id": "9(c)(i)", "marks": 2, "text": "Study Figure 9a in the Resource Booklet. Identify the countries labelled in Figure 9a with the highest and lowest levels of extreme poverty.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV06", "ms": "AO3 (2 marks)\n\nAward 1 mark for any of the following, up to a maximum of 2 marks.\n\n• Highest = Democratic Republic of the Congo\n• Lowest = United Kingdom (2)", "sources": [{"src": "p2-2022R-q9-p64.jpg", "figs": ["9a"]}]}, {"key": "P2-2022R-9cii", "paper": "2022R", "paperLabel": "June 2022 · Paper 2R", "q": 9, "id": "9(c)(ii)", "marks": 4, "text": "Suggest two possible reasons for the pattern shown in Figure 9a.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV06", "ms": "AO2 (2 marks) / AO3 (2 marks)\n\nAward 1 mark (AO1) for identification of a possible reason and a further mark (AO2) for an explanation of the reason, up to a maximum of 2 marks per idea:\n\n• The level of a country’s development may impact the level of people in extreme poverty (1) as those with higher levels of development should have a better standard of living with lower poverty (1).\n\n• Conflict may lead to higher levels of extreme poverty (1) as it may lead to some people not being able to access basic provisions such as food and water (1).\n\n• Low levels of GDP may lead to higher number of people in extreme poverty (1) as people are not able to earn enough to pay for basic food supplies (1).\n\nAccept any other appropriate response.\n(4)", "sources": [{"src": "p2-2022R-q9-p64.jpg", "figs": ["9a"]}]}, {"key": "P2-2022R-9d", "paper": "2022R", "paperLabel": "June 2022 · Paper 2R", "q": 9, "id": "9(d)", "marks": 4, "text": "Explain one advantage and one disadvantage of top-down development projects.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV09", "ms": "AO1 (2 marks) / AO2 (2 marks)\n\nAward 1 mark (AO1) for advantage or disadvantage and a further mark (AO2) for an explanation, up to a maximum of 2 marks for advantage or disadvantage.\n\n• Advantages:\no Can lead to large scale infrastructure improvements (1) which can have positive effects on different aspects of society e.g. trade with the ability to move goods more easily for export (1).\no Often on a large scale (1) so can benefit whole regions or countries e.g. entire coast of Nigeria when railway when completed.\n• Disadvantages:\no Often involves large amount of money through loans (1) which can increase national debt (1).\no Often don’t involve local people in decision making process (1) so benefits don’t necessarily trickle down as planned (1).\n\nAccept any other appropriate response. (4)", "sources": []}, {"key": "P2-2022R-9ei", "paper": "2022R", "paperLabel": "June 2022 · Paper 2R", "q": 9, "id": "9(e)(i)", "marks": 2, "text": "Study Figure 9b in the Resource Booklet. Calculate the percentage decrease in the mortality rate in Bolivia from 1990 to 2018. You must show all your workings in the space below. Give your answer to one decimal place.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV04", "ms": "AO4 (2 marks)\n\nAward 1 mark for a correct answer and one mark for working:\n\n1990= 12.6 2018 = 6.8 (1)\n\nPercentage decrease = 46.0 (1) (2)\n\nAllow 1990 = 12.7 / 6.7 If 12.7 and 6.8. Percentage decrease = 46.5 If 12.7 and 6.7. Percentage decrease = 47.2 If 12.6 and 6.7. Percentage decrease =46.8", "sources": [{"src": "p2-2022R-q9-p65.jpg", "figs": ["9b"]}]}, {"key": "P2-2022R-9eii", "paper": "2022R", "paperLabel": "June 2022 · Paper 2R", "q": 9, "id": "9(e)(ii)", "marks": 2, "text": "Suggest what this trend might mean for the country’s development.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV04", "ms": "AO3 (2 marks)\n\nAward 1 mark for the identification of a pattern and 1 mark for further detail through description or use of supporting data from the resource, up to a maximum of 2 marks.\n\n• The continued decline in mortality rate might suggest it is becoming more developed (1) likely due to be improvements in healthcare (1).\n\n• The decline of the mortality rate from over 12 per 1,000 to under 7 per 1000 (1) suggests it is becoming more developed (1).\n\nAccept any other appropriate response.\n(2)", "sources": [{"src": "p2-2022R-q9-p65.jpg", "figs": ["9b"]}]}, {"key": "P2-2022R-9f", "paper": "2022R", "paperLabel": "June 2022 · Paper 2R", "q": 9, "id": "9(f)", "marks": 6, "text": "Study Figure 9c in the Resource Booklet. Assess the factors that affect uneven development within countries.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV07", "ms": "AO3 (3 marks)/AO4 (3 marks)\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the levels-based mark scheme below.\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. Relevant points may include:\n\nAO3\n• The most important factor for affecting uneven development within a country will vary depending on national circumstances.\n• Where countries have a physical landscape that affects population density and accessibility this is likely to affect development, for example the remote northern regions of Pakistan.\n• Many of the factors that affect uneven development are interlinked, for example people need efficient transport systems to be able to access services and reach suitable employment.\n• There could be some other factors that affect some regions which are not part of this diagram, e.g. availability of natural resources to fuel industry, quality of governance, level of corruption and economic development.\n\nAO4\n• Figure 9c show a range of factors that can affect uneven development within countries.\n• Figure 9c shows how factors that affect uneven development within countries can be categorised as environmental, social and economic.\n• Figure 9c shows how some of these factors are physical and some are human.\n\nLevel Mark Descriptor 0 No rewardable material.\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)", "sources": [{"src": "p2-2022R-q9-p66.jpg", "figs": ["9c"]}]}, {"key": "P2-2022R-9g", "paper": "2022R", "paperLabel": "June 2022 · Paper 2R", "q": 9, "id": "9(g)", "marks": 12, "text": "Discuss the view ‘The most effective way to address inequality within countries is to reduce poverty.’ Use Figures 9a and 9c from the Resource Booklet, and your own knowledge and understanding to support your answer.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV07", "ms": "AO2 (4 marks), AO3 (4 marks), AO4 (4 marks)\n\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the levels-based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. Relevant points may include:\nThe most effective way to address inequality within countries is to tackle poverty”.\n\nAO2\n• Poverty is a condition where people lack the resources for a minimum standard of living. The threshold for poverty will differ between countries.\n• There are a range of factors that affect inequality within countries, including economic, social and environmental factors.\n• Tackling poverty is high on the agenda of many international organisations, such as the World Bank, in order reduce the development gap between countries. Tackling inequality within countries tends more to be the focus of national and regional governments.\n\nAO3\n• Many would argue that patterns of inequality are complex and that by addressing a number of issues such as availability of employment or access to services this may in turn tackle poverty.\n• Tackling poverty is often the focus of activities of many NGOs, trying to support communities that lack basic supplies and services (such as water, food and education). Where people can be supported to have a higher income and not be considered living in poverty this can reduce overall inequality.\n• Inequality can be affected by physical factors too which may require more than just tackling poverty whether at a national or local level. This can require actions from national and international organisations in order to help improve access and transport options to allow residents to travel, communicate and do business with other areas of the country which may in turn improve their quality of life.\n\nAO4\n\n• Figure 9a shows the global distribution of populations with high levels of extreme poverty.\n• Figure 9a shows how central and southern Africa as well as several countries in south Asia, particularly India, have high proportions of their populations living in extreme poverty.\n• Figure 9a indicates that much of the developed world has relatively low proportions of their population living in extreme poverty.\n• Figure 9c shows a range of factors that can affect uneven development within countries.\n• Figure 9c shows how factors that affect uneven development within countries can be categorised as environmental, social, and economic.\n• Figure 9c shows how some of these factors are physical and some are human.\n\nLevel Mark Descriptor 0 No acceptable response.\nLevel 1 1–4 • Demonstrates isolated elements of understanding of concepts and the interrelationship between places, environments and processes. (AO2)\n• Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements are supported by limited evidence. (AO3)\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (A04)\nLevel 2 5–8 • Demonstrates elements of understanding of concepts and the interrelationship between places, environments and processes. (AO2)\n• Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\nLevel 3 9–12 • Demonstrates accurate understanding of concepts and the interrelationship of places, environments and processes. (AO2)\n• Applies understanding to deconstruct information and provides logical connections between concepts throughout. A balanced, well-developed argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4) with its registered office at 80 Strand, London, WC2R 0RL, United Kingdom", "sources": [{"src": "p2-2022R-q9-p64.jpg", "figs": ["9a"]}, {"src": "p2-2022R-q9-p66.jpg", "figs": ["9c"]}]}, {"key": "P2-2021-9ai", "paper": "2021", "paperLabel": "Summer 2021 · Paper 2", "q": 9, "id": "9(a)(i)", "marks": 1, "text": "Identify the main characteristic of top down development.", "intro": "", "options": [["A", "Usually involves decisions at the local level."], ["B", "Usually involves government decisions."], ["C", "Usually involves small amounts of funding."], ["D", "Usually involves the ideas of local people."]], "answer": "B", "type": "mcq", "lesson": "IGDV09", "ms": "AO1 (1 mark)\n\nB - Usually involves government decisions. (1)\n\nA, C and D are incorrect as they are not features of top down development.\n(1)", "sources": []}, {"key": "P2-2021-9aii", "paper": "2021", "paperLabel": "Summer 2021 · Paper 2", "q": 9, "id": "9(a)(ii)", "marks": 2, "text": "Explain what is meant by the term international aid.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV08", "ms": "AO1 (2 marks)\n\nAward 2 marks for a suitable explanation.\n\n• Aid given from one international government or organisation to another country (1) this could be in the form of money or goods (1).\n• Aid given from one country to another (1) which can have conditions attached (1).\n\nAccept any other appropriate response.\n(2)", "sources": []}, {"key": "P2-2021-9aiii", "paper": "2021", "paperLabel": "Summer 2021 · Paper 2", "q": 9, "id": "9(a)(iii)", "marks": 1, "text": "Identify one type of project that could be created by a non-governmental organisation (NGO).", "intro": "", "options": [["A", "Large investments in high speed rail network."], ["B", "Facilitating increases in trade between two national governments."], ["C", "Improving water supplies in an informal settlement."], ["D", "Large investments in national agricultural development."]], "answer": "C", "type": "mcq", "lesson": "IGDV09", "ms": "AO1 (1 mark)\n\nC - Improving water supplies in an informal settlement. (1)\n\nA, B and D are incorrect as they are not projects that an NGO would engage in.\n(1)", "sources": []}, {"key": "P2-2021-9bi", "paper": "2021", "paperLabel": "Summer 2021 · Paper 2", "q": 9, "id": "9(b)(i)", "marks": 1, "text": "Study Figure 9a in the Resource Booklet. Identify the age group with the largest population in 2015.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV04", "ms": "AO3 (1 mark)\n\n45-49 (1)\n(1)", "sources": [{"src": "p2-2021-q9-p64.jpg", "figs": ["9a"]}]}, {"key": "P2-2021-9bii", "paper": "2021", "paperLabel": "Summer 2021 · Paper 2", "q": 9, "id": "9(b)(ii)", "marks": 2, "text": "Compare the population structures of the United Kingdom in 1980 and 2015.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV04", "ms": "AO4 (2 marks)\n\nAward 1 mark for the comparison from Figure 9a and a further mark for additional development, up to a maximum of 2 marks per idea.\n\n• The population sizes in all age groups are larger in 2015 than in 1980 (1). In 1980 only a couple of age groups for males or females reached over 2 million, where as in 2015 there are many groups that reach over this amount (1).\n• There are significantly more older females in the UK in 2015 (over 2 million) (1) compared to just over 1 million in 1980. (1)\n• The shape of the population pyramid has changed (1) with a greater proportion of the population in older age categories as well as the younger in 2015 (1).\n\nAccept any other appropriate response.\n\nUse of data is not required to obtain marks.\n(2)", "sources": []}, {"key": "P2-2021-9biii", "paper": "2021", "paperLabel": "Summer 2021 · Paper 2", "q": 9, "id": "9(b)(iii)", "marks": 2, "text": "Identify one reason for the changes in population structure between 1980 and 2015.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV04", "ms": "AO2 (2 marks)\n\nAward 1 mark (AO3) for identification of a reason and a further mark for development of the reason (AO2), up to a maximum of 2 marks.\n\n• Increased life expectancy (1) due to increases in healthcare (1).\n• Reduced infant mortality rate (1) which means greater amounts of population reach the older age groups (1).\n• Migration of young migrants often male (1) may shift the gender balance in younger groups (1).\n\nAccept any other appropriate response.\n(2)", "sources": []}, {"key": "P2-2021-9biv", "paper": "2021", "paperLabel": "Summer 2021 · Paper 2", "q": 9, "id": "9(b)(iv)", "marks": 2, "text": "Suggest one reason population structure can be an indicator of the level of development.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV04", "ms": "AO2 (1 mark )/AO3 (1 mark)\n\nAward 1 mark (AO3) for identification of a reason and a further mark for development of the reason (AO2), up to a maximum of 2 marks.\n\n• Population structures in developing countries tend to be more pyramid shaped (1) as they usually have higher birth rates. (1)\n• Population structures in developed countries tend to have greater proportions in older age groups (1) as health care services and medical provision can increase life expectancy. (1)\n\nAccept any other appropriate response.\n(2)", "sources": []}, {"key": "P2-2021-9c", "paper": "2021", "paperLabel": "Summer 2021 · Paper 2", "q": 9, "id": "9(c)", "marks": 2, "text": "State two reasons why development can be uneven within a country.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV07", "ms": "AO1 (2 marks)\n\nAward 1 mark for each reason, up to a maximum of 2 marks.\n\n• Transport infrastructure. (1)\n• Provision of healthcare/education services. (1)\n• Investment. (1)\n• Physical landscape. (1)\n• Government investment / establishment of enterprise zones (1).\n\nAccept any other appropriate response.\n(2)", "sources": []}, {"key": "P2-2021-9d", "paper": "2021", "paperLabel": "Summer 2021 · Paper 2", "q": 9, "id": "9(d)", "marks": 4, "text": "Explain one advantage and one disadvantage of a bottom-up development project in a named developing or emerging country.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV09", "ms": "AO1 (2 marks) /AO2 (2 marks)\n\nAward 1 mark for initial identification of an advantage or disadvantage and an additional 1 mark for development through further explanation or exemplification.\n\nA range of country examples could be used.\n\nAdvantages:\n• More likely to suit the needs of local people (1) and use appropriate technology. (1)\n• More likely to use local people and local skills (1) which means they are more likely to be involved in maintenance later. (1)\n\nDisadvantages:\n• Usually projects are small scale (1) so do not necessarily impact large numbers of people. (1)\n• Cannot have large scale impact on national systems (1) and so their potential to create long term change is minimised. (1)\n\nAccept any other appropriate response.\n\n(4)", "sources": []}, {"key": "P2-2021-9e", "paper": "2021", "paperLabel": "Summer 2021 · Paper 2", "q": 9, "id": "9(e)", "marks": 6, "text": "Study Figure 9b in the Resource Booklet. Assess the importance of food security on the global pattern of human welfare.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV06", "ms": "AO3 (3 marks)/AO4 (3 marks)\n\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the levels- based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. Relevant points may include the following.\n\nA03\n• Food security is an important element of human welfare as it affects the ability of populations to prosper. Much like many resources, the distribution of food is uneven, leading to some areas of the world being more prosperous than others.\n• Low food security is likely to lead to low human welfare, as it is a basic need. Poor access to food, suggests the possibilities of malnutrition and poor health which overall leads to poor standards of human welfare.\n• Food security is just one element of human welfare, which can be affected by other economic, social and environmental aspects of societies.\n• Human welfare is a complex subject which can affect the overall pattern globally.\n\nA04\n\n• Figure 9b shows the global distribution of food security.\n• Figure 9b shows how there are low levels of food security in most of Africa, South East Asia and some parts of Latin America.\n• Figure 9b shows how most of the northern hemisphere is considered to be more secure according to the Food Security Index.\n• Figure 9b shows how the pattern of food security broadly fits with the global pattern of north/south development divide.\n(6)\n\nLevel Mark Descriptor 0 No rewardable material.\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements are supports by limited evidence. (AO3)\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (A04)\nLevel 2 4–6 • Applies understanding to deconstruct information but understanding and connections are flawed. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n• Uses geographical skills to obtain information that supports some aspects of the argument. (A04)", "sources": [{"src": "p2-2021-q9-p65.jpg", "figs": ["9b"]}]}, {"key": "P2-2021-9f", "paper": "2021", "paperLabel": "Summer 2021 · Paper 2", "q": 9, "id": "9(f)", "marks": 12, "text": "Discuss the view: 'Demographic characteristics are the most important factors that can affect economic development'. Use Figures 9a and 9c in the Resource Booklet, and your own knowledge and understanding to support your answer.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV04", "ms": "AO2 (4 marks)/AO3 (4 marks) /AO4 (4 marks)\n\nMarking instructions\n\nMarkers must apply the descriptors in line with the general marking guidance and the qualities outlined in the levels-based mark scheme below.\n\nIndicative content guidance\n\nThe indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. Relevant points may include the following.\n\nDemographic indicators are the most important factors that can affect development. A02\n• Demographic characteristics including birth rate, death rate, infant mortality rate, maternal mortality rate etc are important factors that can affect a population’s development pathway.\n• Demographic characteristics are often used as an indicator of stage of development in the demographic transition model, but they are depicted more as a consequence of development stage rather than a factor affecting the development.\n• Some demographic characteristics act as a barrier to development processes including high death rates, and low life expectancy.\nAO3\n\n• There are a wide range of factors that can affect economic development from availability of resources (natural resources, technology, enterprise, innovation and labour), external boosters (globalisation, presense of TNCs, and geopolitics), and internal situations (government policies, business culture).\n• The Human Development Index is comprised of a number of indicators (life expectancy, education, per capita income) – demographics are a key part of this but as a component of a more complex system.\nAO4\n• Figure 9a shows demographic change for the population of the UK through population pyramids.\n• Figure 9a shows how there is an ageing population in the UK with higher proportions of the population in older age groups in 2015 than in 1980.\n• Figure 9c shows a selection of factors that can affect global development in order of importance. While demographic factors are important it highlights the need to acknowledge a wider range of factors also including literacy rate, political stability, natural resources, labour and technology.\n\nLevel Mark Descriptor 0 No rewardable material.\nLevel 1 1–4 • Demonstrates isolated elements of understanding of concepts and the interrelationship between places, environments and processes. (AO2)\n• Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements are supports by limited evidence. (AO3)\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (A04)\nLevel 2 5–8 • Demonstrates elements of understanding of concepts and the interrelationship between places, environments and processes. (AO2)\n• Applies understanding to deconstruct information but understanding and connections are flawed. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n• Uses geographical skills to obtain information that supports some aspects of the argument. (A04)\nLevel 3 9-12 • Demonstrates accurate understanding of concepts and the interrelationship between places, environments and processes. (AO2)\n• Applies understanding to deconstruct information and provides logical connections between concepts throughout.\nA balanced well-developed argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n• Uses geographical skills to obtain information that supports all aspects of the argument. (A04) with its registered office at 80 Strand, London, WC2R 0RL, United Kingdom", "sources": [{"src": "p2-2021-q9-p64.jpg", "figs": ["9a"]}, {"src": "p2-2021-q9-p66.jpg", "figs": ["9c"]}]}, {"key": "P2-2019-9ai", "paper": "2019", "paperLabel": "June 2019 · Paper 2", "q": 9, "id": "9(a)(i)", "marks": 1, "text": "Identify the meaning of the term quality of life.", "intro": "", "options": [["A", "a person’s well-being in terms of health and happiness"], ["B", "a person’s level of deprivation"], ["C", "a person’s cultural identity"], ["D", "a person’s type of employment and income level"]], "answer": "A", "type": "mcq", "lesson": "IGDV01", "ms": "AO1 (1 mark)\n\nA a person’s well-being in terms of health and happiness (1)\n\nA is the correct answer as the other options do not have the correct meaning of the term.", "sources": []}, {"key": "P2-2019-9aii", "paper": "2019", "paperLabel": "June 2019 · Paper 2", "q": 9, "id": "9(a)(ii)", "marks": 1, "text": "Identify the meaning of the term inequality.", "intro": "", "options": [["A", "poor access to resources and services"], ["B", "good access to resources and services"], ["C", "equal access to resources and services"], ["D", "unequal access to resources and services"]], "answer": "D", "type": "mcq", "lesson": "IGDV03", "ms": "D unequal access to resources and services (1)\n\nD is the correct answer as the other options do not have the correct meaning of the term.", "sources": []}, {"key": "P2-2019-9b", "paper": "2019", "paperLabel": "June 2019 · Paper 2", "q": 9, "id": "9(b)", "marks": 1, "text": "Define the term development gap.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV06", "ms": "AO1 (1 mark)\n\n• The widening difference in levels of development between the world's richest and poorest countries (1).\n• Differences in development between countries (1).\n• Differences in development within a country (1).\n• A “gap” or disparity between the richest and poorest people (in the world) (1).\n\nAccept any other appropriate response, including ideas around inequality and uneven development globally, regionally or within a country. (1)", "sources": []}, {"key": "P2-2019-9ci", "paper": "2019", "paperLabel": "June 2019 · Paper 2", "q": 9, "id": "9(c)(i)", "marks": 2, "text": "Study Figure 9a in the Resource Booklet. Identify two countries labelled in Figure 9a with the highest and lowest inequality.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV03", "ms": "AO3 (2 marks)\n\nAward 1 mark for any of the following, up to a maximum of 2 marks.\n\n• Highest = South Africa (1)\n• Lowest = Norway (1) (2)", "sources": [{"src": "p2-2019-q9-p71.jpg", "figs": ["9a"]}]}, {"key": "P2-2019-9cii", "paper": "2019", "paperLabel": "June 2019 · Paper 2", "q": 9, "id": "9(c)(ii)", "marks": 4, "text": "Suggest two reasons for the pattern shown on Figure 9a.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV03", "ms": "AO2 (2 marks) / AO3 (2 marks)\n\nAward 1 mark for the identification of a possible reason for the pattern shown on Figure 9a (AO3) and a further mark for an explanation of the reason (AO2), up to a maximum of 2marks per idea.\n\n• In countries with high inequality, e.g. China (1) have different historical contexts which have lead to inequality (1).\n\n• In countries with high inequality such as many LICs (1) they are less wealthy and possibly more corrupt (1).\n\n• In countries with low inequality such as Norway (1) then they have fairer political systems (1).\n\nAccept any other appropriate response.\n(4)\nNote: Specific countries or regions do not need to be identified for credit.", "sources": [{"src": "p2-2019-q9-p71.jpg", "figs": ["9a"]}]}, {"key": "P2-2019-9d", "paper": "2019", "paperLabel": "June 2019 · Paper 2", "q": 9, "id": "9(d)", "marks": 4, "text": "Explain how two international strategies have attempted to reduce uneven development.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV08", "ms": "AO1 (2 marks) / AO2 (2 marks)\n\nAward 1 mark (AO1) for the identification of a strategy and a further mark (AO2) for an explanation of the reason, up to a maximum of 2 marks per idea:\n\n• Official aid can be used to provide loans to some people (1) so that they are able to buy equipment in order to farm more efficiently (1).\n\n• Bilateral aid works by a government giving aid to another countries government (1) so this could be used to help an economy develop, e.g. supporting the development of natural resources (1).\n• Trade can be used as a tool to stimulate economic development (1) by encouraging the flows of goods and services between nations (1).\n\nAccept any other appropriate response. (4)", "sources": []}, {"key": "P2-2019-9ei", "paper": "2019", "paperLabel": "June 2019 · Paper 2", "q": 9, "id": "9(e)(i)", "marks": 2, "text": "Study Figure 9b in the Resource Booklet. Calculate the range in HDI for Thailand, 1980-2016. You must show all your workings in the space below.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV03", "ms": "AO4 (2 marks)\n\nAward 1 mark for a correct answer and 1 mark for working:\n\n1980 = 0.495 (or 0.49) and 2016 = 0.74 (1) or working out with similar numbers, i.e. understands idea of difference / subtraction (highest and lowest values).\n\nRange = 0.25 or 0.245 (1)\n\nAllow 0.24 - 0.26 as correct. (2)", "sources": [{"src": "p2-2019-q9-p72.jpg", "figs": ["9b"]}]}, {"key": "P2-2019-9eii", "paper": "2019", "paperLabel": "June 2019 · Paper 2", "q": 9, "id": "9(e)(ii)", "marks": 2, "text": "Describe how HDI has changed in Tunisia, 1980-2016.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV03", "ms": "AO3 (2 marks)\n\nAward 1 mark for the identification of a change and 1 mark for further detail through description from the resource, up to a maximum of 2 marks.\n\n• It has increased (1) but then decreased since 2010. (1).\n\n• It has increased (1) but rates of increase vary considerably over the time period. (1).\n\n• It has overall increased (1) with the steepest rate of increase between 1980 and 2000 (1).\n\n• There is mostly a gentle rate of increase (1), although the period 2000-2010 shows a more rapid rate of change (1).\n(2)\nAccept any other appropriate response.\n\nExplicit data not required for 2 marks.", "sources": []}, {"key": "P2-2019-9f", "paper": "2019", "paperLabel": "June 2019 · Paper 2", "q": 9, "id": "9(f)", "marks": 6, "text": "Study Figure 9c in the Resource Booklet. Assess the different factors that have caused variations in global development.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV06", "ms": "AO3 (3 marks)/AO4 (3 marks)\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the levels-based mark scheme below.\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. Relevant points may include:\nAO3\n• The most important factors are likely to be governments and the availability of resources. But the effects of these will vary spatially and will depend on the geo-political arrangements in that country / region.\n• Longer term, climate change is perhaps most significant as nations become both more developed and more populous – therefore the scale of this one is large.\n• Food and water security may be more localised in some regions and some places, but with increased globalisation, this is a factor that in the future will likely be very significant.\n• Causal factors are often interlinked and there can be a chain of events that encourage uneven development\n• There could be some factors that in some regions are local or political which are not on this list and should not be overlooked.\n\nAO4\n• Figure 9c shows a range of different causes which are all possible drivers of uneven global development.\n• Figure 9c shows causes that can operate at different geographical scales.\n• Figure 9c indicates that there is only a limited number of causes, but for some places there may be more.\nLevel Mark Descriptor 0 No rewardable material.\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)", "sources": [{"src": "p2-2019-q9-p73.jpg", "figs": ["9c"]}]}, {"key": "P2-2019-9g", "paper": "2019", "paperLabel": "June 2019 · Paper 2", "q": 9, "id": "9(g)", "marks": 12, "text": "Discuss the view: “International strategies are only one part of the solution to closing the development gap”. Use Figures 9a, 9b and 9c from the Resource Booklet and your own knowledge and understanding to support your answer.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV08", "ms": "AO2 (4 marks), AO3 (4 marks), AO4 (4 marks)\n\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the levels-based mark scheme below.\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. Relevant points may include:\n\nAO2\n• There are arrange of factors that control uneven development including social, economic, political as well as environmental\n• Uneven development is strongly associated with the development gap\n• There are different strategies from local, regional, national and international that can be used in an attempt to reduce inequality\nAO3\n• A main impact of inequality lack of available and access to resources. However, different groups of people have different opinions about which strategy is the best/most effective – so this is complex to manage.\n• The challenge of global management of the issue is that crosses international boundaries – and therefore international cooperation is crucial– but these agreements are never straight forward to arrive at, or to implement. Different countries and placers will have different approaches to sustainability.\n• Fertility and IMR is very strongly linked to sustainable development, and some would argue the “gap”. Solutions based on family planning may be national as well as international\n• Inequality can vary spatially and temporally, which means that management solutions often have to be tailored locally or regionally, so the global aspect is difficult.\n• Each (sustainable) development strategy has its own advantages and disadvantages.\nAO4\n\n• Figure 9a shows that big differences global inequality rates in 2017\n• Figure 9a shows red “hotspots” of South Africa and parts of the S America, Russia and China, whereas the lowest rates are in Canada and Scandinavia in northern Europe\n• Figure 9b shows a range of different trends for different regions based on HDI.\n• Figure 9b shows Tunisia and Brazil have had marked decreases in the HDIs since 2010.\n• Figure 9b shows on comparison most regions have had similar rates of increase in HDI, but since 2010 the rates have increase has slowed in most regions.\n• Figure 9c shows causes that can operate at different geographical scales.\n• Figure 9c indicates that there is only a limited number of causes, but for some places there may be more.\nLevel Mark Descriptor 0 No acceptable response.\nLevel 1 1–4 • Demonstrates isolated elements of understanding of concepts and the interrelationship between places, environments and processes. (AO2)\n• Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements are supported by limited evidence. (AO3)\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (A04)\nLevel 2 5–8 • Demonstrates elements of understanding of concepts and the interrelationship between places, environments and processes. (AO2)\n• Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\nLevel 3 9–12 • Demonstrates accurate understanding of concepts and the interrelationship of places, environments and processes. (AO2)\n• Applies understanding to deconstruct information and provides logical connections between concepts throughout. A balanced, well-developed argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4) with its registered office at 80 Strand, London, WC2R 0RL, United Kingdom", "sources": [{"src": "p2-2019-q9-p71.jpg", "figs": ["9a"]}, {"src": "p2-2019-q9-p72.jpg", "figs": ["9b"]}, {"src": "p2-2019-q9-p73.jpg", "figs": ["9c"]}]}, {"key": "P2-2019R-9ai", "paper": "2019R", "paperLabel": "June 2019 · Paper 2R", "q": 9, "id": "9(a)(i)", "marks": 1, "text": "Identify one factor that could be used as a measure of development.", "intro": "", "options": [["A", "participation in sport"], ["B", "water availability"], ["C", "index of political corruption"], ["D", "bottom-up development"]], "answer": "C", "type": "mcq", "lesson": "IGDV02", "ms": "AO1 (1 mark)\n\nC index of political corruption (1)\n\nC is the correct answer as the other options do not include relevant measures of development", "sources": []}, {"key": "P2-2019R-9aii", "paper": "2019R", "paperLabel": "June 2019 · Paper 2R", "q": 9, "id": "9(a)(ii)", "marks": 1, "text": "Identify the meaning of the term fertility rate.", "intro": "", "options": [["A", "the number of live births per thousand of population per year"], ["B", "the number of deaths in a particular population"], ["C", "the number of births in the total population"], ["D", "the number of births per woman in a population"]], "answer": "D", "type": "mcq", "lesson": "IGDV04", "ms": "AO1 (1 mark)\n\nD the number of births per woman in a population (1)\n\nD is the correct answer as the other options are incorrect in relation to the options", "sources": []}, {"key": "P2-2019R-9bi", "paper": "2019R", "paperLabel": "June 2019 · Paper 2R", "q": 9, "id": "9(b)(i)", "marks": 1, "text": "Define the term water security.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV06", "ms": "AO1 (1 mark)\n\n• The (reliable) availability of water with an acceptable quantity (and quality) for health and livelihoods (1).\n• A place has enough water that is drinkable / the right quality (1).\n• Having access to clean available water (1).\n• Sustainable amount of water of acceptable quality (1) (1)\n• A country is able to meet its water demands (1)\n\nAccept any other appropriate response. Must have idea of availability or “enough” for credit.", "sources": []}, {"key": "P2-2019R-9bii", "paper": "2019R", "paperLabel": "June 2019 · Paper 2R", "q": 9, "id": "9(b)(ii)", "marks": 2, "text": "Study Figure 9a in the Resource Booklet. Identify two countries labelled in Figure 9a with an HDI of less than 48.00.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV03", "ms": "AO3 (2 marks)\n\nAward 1 mark for any of the following, up to a maximum of 2 marks.\n\n• Ethiopia (1)\n• Madagascar (1) (2)", "sources": [{"src": "p2-2019R-q9-p64.jpg", "figs": ["9a"]}]}, {"key": "P2-2019R-9biii", "paper": "2019R", "paperLabel": "June 2019 · Paper 2R", "q": 9, "id": "9(b)(iii)", "marks": 4, "text": "Suggest two possible reasons for the pattern shown on Figure 9a.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV03", "ms": "AO2 (2 marks) / AO3 (2 marks)\n\nAward 1 mark for the identification of a pattern shown on the map (AO3) and a further mark for an explanation of the reason (AO2), up to a maximum of 2 marks per idea.\n\n• In the north hemisphere there is generally high HDI (1) as there has been government policy promoting education and training (1).\n\n• In much of Africa there is low HDI (1) since there is often low levels of technology penetration (1).\n\n• Place such as South Africa have a medium HDI (1) as they tend to have more political stability (1).\n\n• Much of Europe has a high level of HDI (1) as ether are very low levels of political interference and corruption (1).\n\nAccept any other appropriate response.\nNote: Pattern can refer to individual countries, data from key or regions, e.g. Europe, EU etc.\n\n(4)", "sources": [{"src": "p2-2019R-q9-p64.jpg", "figs": ["9a"]}]}, {"key": "P2-2019R-9c", "paper": "2019R", "paperLabel": "June 2019 · Paper 2R", "q": 9, "id": "9(c)", "marks": 4, "text": "Explain two impacts of uneven development on the quality of life within a country.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV07", "ms": "AO1 (2 marks) / AO2 (2 marks)\n\nAward 1 mark (AO1) for identification of effect and a further mark (AO2) for an explanation of the reason, up to a maximum of 2 marks per idea:\n\n• Uneven development within a country can lead to cores and periphery (1) so this means inequality in terms of incomes and employment opportunity (1).\n• Poverty may be unequal at a range of different scales within a country (1) so consumers and businesses are split into the “haves” and “have-nots”. (1).\n\n• Spatial disparities can often be seen in terms of physical infrastructure, e.g. road and rail networks (1) and places can either feel connected or distant and inaccessible (1).\n\nAccept any other appropriate response.\n(4)", "sources": []}, {"key": "P2-2019R-9di", "paper": "2019R", "paperLabel": "June 2019 · Paper 2R", "q": 9, "id": "9(d)(i)", "marks": 2, "text": "Study Figure 9b in the Resource Booklet. Calculate the range in infant mortality for South Asia between 1960 and 2012. You must show all your workings in the space below.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV04", "ms": "AO4 (2 marks)\n\nAward 1 mark for a correct answer and one mark for working:\n\n1960 = 250 and 2012 = 60 (1) or working out with similar numbers, i.e. understands idea of difference / subtraction (highest and lowest values). Numbers may be in millions as well.\n\nRange = 190 (1)\n\nAllow 185 – 195\n\nNote units not required. (2)", "sources": [{"src": "p2-2019R-q9-p65.jpg", "figs": ["9b"]}]}, {"key": "P2-2019R-9dii", "paper": "2019R", "paperLabel": "June 2019 · Paper 2R", "q": 9, "id": "9(d)(ii)", "marks": 2, "text": "Describe the extent to which infant mortality rates have changed from 1960-2012 in Figure 9b.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV04", "ms": "AO3 (2 marks)\n\nAward 1 mark for the identification of a pattern and 1 mark for further detail through description or use of supporting data from the resource, up to a maximum of 2 marks.\n\n• In all regions (countries) IMR have decreased (1) but rates of decrease vary considerably (1).\n\n• Some regions show even / linear rates of decrease in IMR over time, e.g. N America (1) whereas Sub-Saharan Africa shows a more variable rate 1963-2012 (1).\n\n• The biggest absolute decline is in the Middle East and North Africa (260-30 – 1960-2012) (1), whereas North America has seen a very low decline over the same time period (1).\n(2)\nAccept any other appropriate response.\nNote: explicit use of data not required for max 2 marks.", "sources": [{"src": "p2-2019R-q9-p65.jpg", "figs": ["9b"]}]}, {"key": "P2-2019R-9e", "paper": "2019R", "paperLabel": "June 2019 · Paper 2R", "q": 9, "id": "9(e)", "marks": 6, "text": "Study Figure 9c in the Resource Booklet. Assess the different factors that have caused uneven global development.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV06", "ms": "AO3 (3 marks)/AO4 (3 marks)\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the levels-based mark scheme below.\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. Relevant points may include:\nAO3\n• The most important factors are likely to be world trade and the availability of resource. But the effects of these will vary spatially and will depend on the geo-political arrangements in that country / region.\n• Longer term, climate change and cultural factors are important as nations become both more developed and more populous – therefore the scale of this one is large.\n• Food availability may be more localised in some regions and some places, but with increased globalisation, this is a factor that in the future will likely be very significant.\n• Causal factors are often interlinked and there can be a chain of events that encourage uneven development\n• There could be some factors that in some regions are local or political which are not on this list and should not be overlooked.\n\nAO4\n• Figure 9c shows a range of different causes which are all possible drivers of uneven global development.\n• Figure 9c shows causes that can operate at different geographical scales.\n• Figure 9c indicates that there is only a limited number of causes, but for some places there may be more.\nLevel Mark Descriptor 0 No rewardable material.\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)", "sources": [{"src": "p2-2019R-q9-p66.jpg", "figs": ["9c"]}]}, {"key": "P2-2019R-9f", "paper": "2019R", "paperLabel": "June 2019 · Paper 2R", "q": 9, "id": "9(f)", "marks": 12, "text": "Discuss the view: “Different strategies are needed to reduce the uneven global development”. Use Figures 9a, 9b and 9c from the Resource Booklet and your own knowledge and understanding to support your answer.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGDV08", "ms": "AO2 (4 marks), AO3 (4 marks), AO4 (4 marks)\n\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the levels-based mark scheme below.\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. Relevant points may include:\n\nAO2\n• There are a number of strategies, some local, some regional, some national and some international that can reduce the development gap.\n• Strategies include: aid, fair-trade, trade, debt relief, investment as well as political reform and freedom of speech.\n• There are several groups (players) involved in the management of different strategies, e.g. governments, World Bank, UNESCO, Oxfam and the Red Cross.\nAO3\n• A main cause of inequality / uneven is lack of available and access to resources. However, different groups of people have different opinions about how important this factor might be.\n• A challenge of global management of the issue is that crosses international boundaries – and therefore international cooperation is crucial– but these agreements and strategies are never straight forward to arrive at, or to implement.\n• Fertility and IMR is very strongly linked to uneven development, but arguably are not the main cause, so some could argue the resources are a symptom of uneven development, not the cause.\n• Knowledge and access to education are seen as keen enablers to development through improving people’s quality of life. Others argue that economic development is very significant.\n• Longer term the conditions for creating human development may not be the same as the shorter term, i.e. improving quality of life, access to service, employment. They may in fact be more linked to reducing political corruption through better governance.\n• Development can vary spatially and temporally, which means that management solutions often have to be tailored locally or regionally.\n\nAO4\n\n• Figure 9a shows that big differences in global fertility rates\n• Figure 9a shows red “hotspots” of central Africa and parts of the Middle East and SE Asia, whereas the lowest rates are in parts of North America and Eurasia\n• Figure 9b Shows there is considerable variation in IMR across all countries.\n• Figure 9b shows in all cases IMR drops over time\n• Figure 9b shows South Asia has the largest drop over the 1960-2012 period.\n• Figure 9c shows a range of different causes which are all possible drivers of uneven global development.\n• Figure 9c shows causes that can operate at different geographical scales.\n• Figure 9c indicates that there is only a limited number of causes, but for some places there may be more.\nLevel Mark Descriptor 0 No acceptable response.\nLevel 1 1–4 • Demonstrates isolated elements of understanding of concepts and the interrelationship between places, environments and processes. (AO2)\n• Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements are supported by limited evidence. (AO3)\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (A04)\nLevel 2 5–8 • Demonstrates elements of understanding of concepts and the interrelationship between places, environments and processes. (AO2)\n• Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\nLevel 3 9–12 • Demonstrates accurate understanding of concepts and the interrelationship of places, environments and processes. (AO2)\n• Applies understanding to deconstruct information and provides logical connections between concepts throughout. A balanced, well-developed argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4) with its registered office at 80 Strand, London, WC2R 0RL, United Kingdom", "sources": [{"src": "p2-2019R-q9-p64.jpg", "figs": ["9a"]}, {"src": "p2-2019R-q9-p65.jpg", "figs": ["9b"]}, {"src": "p2-2019R-q9-p66.jpg", "figs": ["9c"]}]}]};
